package api

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"testing"

	"github.com/mellifera/mellifera/internal/identity"
	"github.com/mellifera/mellifera/internal/pairing"
)

// loginBody builds the POST /auth/login request body.
func loginBody(username, password string) string {
	b, _ := json.Marshal(loginRequest{Username: username, Password: password})
	return string(b)
}

// loginProbe fires one login and returns status + raw body bytes — raw bytes
// so the uniformity assertion compares the WIRE response, not a decoded
// struct that could have collapsed distinctions.
func loginProbe(t *testing.T, h http.Handler, username, password string) (int, []byte) {
	t.Helper()
	resp := doRequest(t, h, http.MethodPost, "/api/v1/auth/login", loginBody(username, password), "")
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read login body: %v", err)
	}
	return resp.StatusCode, raw
}

// TestLoginLogoutEndpoint pins the auth session endpoints end to end over
// the REAL router (l6-accounts 7.2): login mints a token that authenticates,
// failures are uniform, the limiter is keyed (IP, username), and logout
// deletes only the presented session row.
func TestLoginLogoutEndpoint(t *testing.T) {
	ctx := context.Background()

	t.Run("login_mints_authenticating_session", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		if _, err := ident.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		granted, hidden := seedGrantedLibrary(t, ident, st, "alia")
		h := authChainRouter(t, st, ident)

		code, raw := loginProbe(t, h, "alia", "pw")
		if code != http.StatusOK {
			t.Fatalf("login status = %d, want 200 (body %s)", code, raw)
		}
		var lr loginResponse
		if err := json.Unmarshal(raw, &lr); err != nil {
			t.Fatalf("decode loginResponse: %v", err)
		}
		if lr.Token == "" {
			t.Fatal("login response carries an empty token")
		}

		// The minted token authenticates AS its user through the real chain
		// (7.1's session leg + 6.1's viewer projection): exactly the granted
		// library is visible, the never-granted one is invisible.
		ids := listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", lr.Token))
		if !ids[granted] || ids[hidden] || len(ids) != 1 {
			t.Fatalf("minted-session library list = %v, want exactly {%d}", ids, granted)
		}

		// An admin-role user's login-minted session projects RoleAdmin at the
		// middleware (D11) and passes requireRole(RoleAdmin) on an admin route.
		if err := ident.SetRole(ctx, "alia", "admin"); err != nil {
			t.Fatalf("SetRole: %v", err)
		}
		adminLogin, adminRaw := loginProbe(t, h, "alia", "pw")
		if adminLogin != http.StatusOK {
			t.Fatalf("post-promotion login status = %d (body %s)", adminLogin, adminRaw)
		}
		var ar loginResponse
		if err := json.Unmarshal(adminRaw, &ar); err != nil {
			t.Fatalf("decode loginResponse: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", ar.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("admin-role minted session on admin route = %d, want 200", resp.StatusCode)
		}
	})

	t.Run("failures_are_byte_identical", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		if _, err := ident.Create(ctx, "gale", "pw"); err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		if err := ident.SetDisabled(ctx, "gale", true); err != nil {
			t.Fatalf("SetDisabled: %v", err)
		}
		h := authChainRouter(t, st, ident)

		wrongPwCode, wrongPwBody := loginProbe(t, h, "gale", "wrong")
		unknownCode, unknownBody := loginProbe(t, h, "nobody", "pw")
		disabledCode, disabledBody := loginProbe(t, h, "gale", "pw")

		for _, c := range []int{wrongPwCode, unknownCode, disabledCode} {
			if c != http.StatusUnauthorized {
				t.Fatalf("login failure status = %d, want 401 across all three refusal shapes", c)
			}
		}
		if !bytes.Equal(wrongPwBody, unknownBody) || !bytes.Equal(wrongPwBody, disabledBody) {
			t.Fatalf("failure bodies differ (enumeration leak): wrong-pw=%s unknown=%s disabled=%s",
				wrongPwBody, unknownBody, disabledBody)
		}
		if eb := decodeError(t, &http.Response{Body: io.NopCloser(bytes.NewReader(wrongPwBody))}); eb.Error.Code != "unauthenticated" {
			t.Fatalf("failure code = %q, want unauthenticated", eb.Error.Code)
		}
	})

	t.Run("burst_429_keyed_by_ip_and_username", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		h := authChainRouter(t, st, ident)

		// Hammer "brute" past the fixed window: the first loginLimitMax
		// attempts fall through to the uniform 401, the next is 429'd.
		// httptest.NewRequest pins RemoteAddr for every request, so the IP
		// leg of the key is constant and the username leg is what varies.
		for i := 0; i < loginLimitMax; i++ {
			code, _ := loginProbe(t, h, "brute", "pw")
			if code != http.StatusUnauthorized {
				t.Fatalf("attempt %d status = %d, want 401 (still inside the window)", i+1, code)
			}
		}
		overCode, overBody := loginProbe(t, h, "brute", "pw")
		if overCode != http.StatusTooManyRequests {
			t.Fatalf("attempt %d status = %d, want 429 (window exhausted)", loginLimitMax+1, overCode)
		}
		if eb := decodeError(t, &http.Response{Body: io.NopCloser(bytes.NewReader(overBody))}); eb.Error.Code != "rate_limited" {
			t.Fatalf("burst code = %q, want rate_limited", eb.Error.Code)
		}

		// A DIFFERENT username from the SAME IP is a different key — it is
		// not blocked (this is what proves the tuple, not just the burst).
		otherCode, _ := loginProbe(t, h, "other", "pw")
		if otherCode != http.StatusUnauthorized {
			t.Fatalf("different-username login status = %d, want 401 (a distinct key must not inherit the block)", otherCode)
		}
	})

	t.Run("logout_deletes_own_row_only", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		if _, err := ident.Create(ctx, "noria", "pw"); err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		h := authChainRouter(t, st, ident)
		s1, err := ident.MintSession(ctx, "noria", "pw")
		if err != nil {
			t.Fatalf("MintSession s1: %v", err)
		}
		s2, err := ident.MintSession(ctx, "noria", "pw")
		if err != nil {
			t.Fatalf("MintSession s2: %v", err)
		}

		resp := doRequest(t, h, http.MethodPost, "/api/v1/auth/logout", "", s1.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("logout status = %d, want 204", resp.StatusCode)
		}

		// The presented session is dead: its reuse 401s.
		dead := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", s1.Token)
		defer dead.Body.Close()
		if dead.StatusCode != http.StatusUnauthorized {
			t.Fatalf("revoked session reuse = %d, want 401", dead.StatusCode)
		}

		// The user's OTHER session survives — logout deletes own row only.
		alive := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", s2.Token)
		defer alive.Body.Close()
		if alive.StatusCode != http.StatusOK {
			t.Fatalf("sibling session after logout = %d, want 200", alive.StatusCode)
		}
	})

	t.Run("device_bearer_logout_refused", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		devices := pairing.NewService(st, nil)
		h := authChainRouter(t, st, ident)

		// A real device credential through the real pairing flow (the
		// TestAuthChainDevices seeding pattern).
		req, err := devices.CreateRequest(ctx, "10.0.0.9")
		if err != nil {
			t.Fatalf("CreateRequest: %v", err)
		}
		if _, err := devices.Approve(ctx, req.ID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		out, err := devices.Wait(ctx, req.ID)
		if err != nil || out.Token == "" {
			t.Fatalf("Wait: outcome=%+v err=%v", out, err)
		}

		// The kind guard: a device bearer has no session row to delete —
		// the refusal is the uniform 401 and the DEVICE row is untouched
		// (the bearer still authenticates afterwards).
		resp := doRequest(t, h, http.MethodPost, "/api/v1/auth/logout", "", out.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("device-bearer logout = %d, want 401 (RevokeSession's kind guard)", resp.StatusCode)
		}
		still := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", out.Token)
		defer still.Body.Close()
		if still.StatusCode != http.StatusOK {
			t.Fatalf("device credential after refused logout = %d, want 200 (row untouched)", still.StatusCode)
		}
	})
}
